// ── CH3 · MOUNTAIN PATH — climbing toward the Ice Kingdom ──

svg += `<defs>
  <linearGradient id="lg-ch3" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN?'#06001A':'#2A3A5A'}"/>
    <stop offset="50%" stop-color="${isN?'#0D0B3E':sc.sky1}"/>
    <stop offset="100%" stop-color="${isN?'#1A1A4A':sc.sky2}"/>
  </linearGradient>
  <linearGradient id="lg-ch3-mtn" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#E0E8F0"/>
    <stop offset="100%" stop-color="#A0B8D0"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch3)"/>`;

// ── Aurora hints (faint, fading) ──
for (let i = 0; i < 3; i++) {
  const ax = w*(0.2+i*0.3);
  const ay = h*0.06+Math.sin(mt*0.4+i*1.2)*h*0.04;
  const aop = 0.03+Math.sin(mt*0.5+i*0.97)*0.02;
  const aCols = ['#00FF88','#7DF9FF','#DA70D6'];
  svg += `<ellipse cx="${ax}" cy="${ay}" rx="${w*0.15}" ry="${h*0.12}" fill="${aCols[i]}" opacity="${aop}"/>`;
}

// Stars
for (let i = 0; i < 30; i++) {
  const sx = (Math.sin(i*127.1+3.7)*0.5+0.5)*w;
  const sy = (Math.sin(i*311.7+1.3)*0.5+0.5)*h*0.35;
  const sr = 0.4+Math.sin(mt*1.2+i*0.9)*0.4;
  const sop = isN?0.6+Math.sin(mt+i*0.5)*0.3:0.08+Math.sin(mt+i)*0.05;
  svg += `<circle cx="${sx}" cy="${sy}" r="${sr}" fill="#FFF" opacity="${sop}"/>`;
}

// ── DISTANT ICE CASTLE (small, on horizon, glowing) ──
const dcx = w*0.78, dcy = h*0.22;
const dcGlow = 15+w2*8;
// Castle silhouette (tiny)
svg += `<rect x="${dcx-8}" y="${dcy-12}" width="16" height="15" rx="1" fill="#A0C8E8" stroke="#80A8C8" stroke-width="1"/>`;
svg += `<rect x="${dcx-12}" y="${dcy-20}" width="6" height="20" rx="1" fill="#A0C8E8" stroke="#80A8C8" stroke-width="1"/>`;
svg += `<polygon points="${dcx-12},${dcy-20} ${dcx-9},${dcy-28} ${dcx-6},${dcy-20}" fill="#B0D8F0"/>`;
svg += `<rect x="${dcx+6}" y="${dcy-24}" width="6" height="24" rx="1" fill="#A0C8E8" stroke="#80A8C8" stroke-width="1"/>`;
svg += `<polygon points="${dcx+6},${dcy-24} ${dcx+9},${dcy-32} ${dcx+12},${dcy-24}" fill="#B0D8F0"/>`;
// Castle glow
svg += `<circle cx="${dcx}" cy="${dcy-10}" r="${dcGlow}" fill="${sc.acc}" opacity="${0.04+w1*0.03}"/>`;
// Flickering windows
for (let i = 0; i < 3; i++) {
  const wpulse = Math.sin(mt*1.8+i*1.3)*0.5+0.5;
  svg += `<rect x="${dcx-6+i*5}" y="${dcy-8+i*2}" width="2" height="3" rx="1" fill="rgba(125,249,255,${0.3+wpulse*0.5})"/>`;
}

// ── FAR MOUNTAINS (background) ──
svg += `<path d="M0 ${h*0.4} Q${w*0.1} ${h*0.28} ${w*0.2} ${h*0.32} Q${w*0.3} ${h*0.22} ${w*0.4} ${h*0.35} Q${w*0.5} ${h*0.25} ${w*0.6} ${h*0.3} Q${w*0.7} ${h*0.18} ${w*0.8} ${h*0.28} Q${w*0.9} ${h*0.32} ${w} ${h*0.36} L${w} ${h} L0 ${h} Z" fill="url(#lg-ch3-mtn)" stroke="#B0C0D0" stroke-width="${ol*0.4}" opacity="0.4"/>`;

// ── MAIN MOUNTAIN (foreground path) ──
svg += `<path d="M0 ${h*0.55} Q${w*0.15} ${h*0.42} ${w*0.35} ${h*0.48} Q${w*0.5} ${h*0.38} ${w*0.65} ${h*0.45} Q${w*0.8} ${h*0.35} ${w} ${h*0.42} L${w} ${h} L0 ${h} Z" fill="${sc.ground}" stroke="#A0B8D0" stroke-width="${ol*0.6}"/>`;
// Snow texture
for (let i = 0; i < 25; i++) {
  const stx = w*(i/25);
  const sty2 = h*0.5+Math.sin(i*1.5)*h*0.04;
  svg += `<ellipse cx="${stx}" cy="${sty2}" rx="12" ry="3" fill="#F0F8FF" opacity="0.2"/>`;
}

// ── Winding path (visible trail up the mountain) ──
const pathPoints = [];
for (let i = 0; i <= 10; i++) {
  const t = i/10;
  const px = w*0.05+t*w*0.85+Math.sin(t*4)*w*0.06;
  const py = h*0.75-t*h*0.35+Math.sin(t*3)*h*0.03;
  pathPoints.push([px,py]);
}
let pathD = `M${pathPoints[0][0]} ${pathPoints[0][1]}`;
for (let i = 1; i < pathPoints.length; i++) pathD += ` L${pathPoints[i][0]} ${pathPoints[i][1]}`;
svg += `<path d="${pathD}" fill="none" stroke="#B0B8C0" stroke-width="8" stroke-linecap="round" opacity="0.25"/>`;
svg += `<path d="${pathD}" fill="none" stroke="#D8E0E8" stroke-width="4" stroke-linecap="round" stroke-dasharray="8,6" opacity="0.35"/>`;

// ── Pine trees along path ──
for (let i = 0; i < 8; i++) {
  const ti = i/8;
  const tx = w*0.08+ti*w*0.8+Math.sin(i*2.3)*20;
  const ty = h*0.72-ti*h*0.3+Math.sin(i*1.7)*10;
  const th = 20+Math.sin(i*1.7)*8;
  const tsw = Math.sin(mt*0.5+i*0.9)*1.5;
  svg += `<line x1="${tx}" y1="${ty}" x2="${tx+tsw}" y2="${ty-th}" stroke="#2E4A2A" stroke-width="2.5"/>`;
  for (let j = 0; j < 3; j++) {
    const tty = ty-th+j*(th*0.3);
    const tw2 = 5+j*3;
    svg += `<polygon points="${tx+tsw},${tty} ${tx-tw2+tsw*0.5},${tty+th*0.22} ${tx+tw2+tsw*0.5},${tty+th*0.22}" fill="#2E5A3A" stroke="#1A3A20" stroke-width="${ol*0.2}"/>`;
    svg += `<line x1="${tx-tw2*0.5+tsw*0.5}" y1="${tty+th*0.22}" x2="${tx+tw2*0.5+tsw*0.5}" y2="${tty+th*0.22}" stroke="#F0F8FF" stroke-width="2" stroke-linecap="round" opacity="0.5"/>`;
  }
}

// ═══ CHARACTERS (walking along the path, ~40% up) ═══
const cBaseX = w*0.35+Math.sin(mt*0.3)*5;
const cBaseY = h*0.58;
const walk = mt*0.8;

// ── Deer (leading) ──
const ddx = cBaseX+50, ddy = cBaseY-8;
const ddB = Math.sin(mt*0.6)*1.5;
svg += `<ellipse cx="${ddx}" cy="${ddy+ddB}" rx="14" ry="9" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.4}"/>`;
svg += `<path d="M${ddx+8} ${ddy-3+ddB} Q${ddx+12} ${ddy-14+ddB} ${ddx+10} ${ddy-22+ddB}" fill="none" stroke="#C4862D" stroke-width="6" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx+10}" cy="${ddy-26+ddB}" r="5" fill="#D4964A"/>`;
svg += `<path d="M${ddx+7} ${ddy-30+ddB} Q${ddx+3} ${ddy-38} ${ddx+2} ${ddy-42}" fill="none" stroke="#8B6B4A" stroke-width="1.3" stroke-linecap="round"/>`;
svg += `<path d="M${ddx+13} ${ddy-30+ddB} Q${ddx+17} ${ddy-38} ${ddx+18} ${ddy-42}" fill="none" stroke="#8B6B4A" stroke-width="1.3" stroke-linecap="round"/>`;
svg += `<circle cx="${ddx+12}" cy="${ddy-27+ddB}" r="1" fill="#222"/>`;
const ddL = Math.sin(walk*2.5)*3;
for (let i = 0; i < 4; i++) svg += `<line x1="${ddx-6+i*5}" y1="${ddy+8+ddB}" x2="${ddx-6+i*5+(i%2===0?ddL:-ddL)}" y2="${ddy+16}" stroke="#A06820" stroke-width="2" stroke-linecap="round"/>`;
// Fawn beside deer
svg += `<ellipse cx="${ddx-14}" cy="${ddy+4+ddB}" rx="8" ry="5" fill="#D4A050"/>`;
svg += `<circle cx="${ddx-10}" cy="${ddy-3+ddB}" r="3.5" fill="#D4A050"/>`;
svg += `<circle cx="${ddx-8}" cy="${ddy-4+ddB}" r="0.8" fill="#222"/>`;

// ── Three pups (middle of group) ──
const pups = [
  {x:cBaseX+15, col:'#FF8C42', scol:'#D06B20', ecol:'#E07830'},
  {x:cBaseX, col:'#9370DB', scol:'#7B5EA7', ecol:'#8060C0'},
  {x:cBaseX-15, col:'#5AAA5A', scol:'#3A8A3A', ecol:'#4A9A4A'}
];
for (let p = 0; p < 3; p++) {
  const px = pups[p].x;
  const py = cBaseY+2+p*2;
  const bob = Math.abs(Math.sin(walk*2.5+p))*2;
  svg += `<ellipse cx="${px}" cy="${py-bob}" rx="6.5" ry="4.5" fill="${pups[p].col}" stroke="${pups[p].scol}" stroke-width="${ol*0.4}"/>`;
  svg += `<circle cx="${px+4}" cy="${py-7-bob}" r="4.5" fill="${pups[p].col}" stroke="${pups[p].scol}" stroke-width="${ol*0.4}"/>`;
  svg += `<polygon points="${px+1},${py-11-bob} ${px},${py-16-bob} ${px+4},${py-12-bob}" fill="${pups[p].ecol}"/>`;
  svg += `<polygon points="${px+7},${py-11-bob} ${px+8},${py-16-bob} ${px+5},${py-12-bob}" fill="${pups[p].ecol}"/>`;
  svg += `<circle cx="${px+3}" cy="${py-8-bob}" r="0.9" fill="#222"/>`;
  svg += `<circle cx="${px+6}" cy="${py-8-bob}" r="0.9" fill="#222"/>`;
  const lf = Math.sin(walk*3+p)*3;
  svg += `<line x1="${px-3}" y1="${py+3-bob}" x2="${px-4+lf}" y2="${py+8}" stroke="${pups[p].scol}" stroke-width="1.8" stroke-linecap="round"/>`;
  svg += `<line x1="${px+3}" y1="${py+3-bob}" x2="${px+4-lf}" y2="${py+8}" stroke="${pups[p].scol}" stroke-width="1.8" stroke-linecap="round"/>`;
}

// ── Owl flying overhead ──
const owlFX = cBaseX+30+Math.sin(mt*0.5)*30;
const owlFY = cBaseY-55+Math.cos(mt*0.4)*10;
const owlWing = Math.sin(mt*3)*8;
svg += `<ellipse cx="${owlFX}" cy="${owlFY}" rx="6" ry="5" fill="#8B6B4A"/>`;
svg += `<circle cx="${owlFX}" cy="${owlFY-5}" r="4" fill="#9B7B5A"/>`;
// Wings flapping
svg += `<path d="M${owlFX-6} ${owlFY} Q${owlFX-16} ${owlFY-owlWing} ${owlFX-20} ${owlFY+2}" fill="none" stroke="#8B6B4A" stroke-width="3" stroke-linecap="round"/>`;
svg += `<path d="M${owlFX+6} ${owlFY} Q${owlFX+16} ${owlFY-owlWing} ${owlFX+20} ${owlFY+2}" fill="none" stroke="#8B6B4A" stroke-width="3" stroke-linecap="round"/>`;
// Owl eyes
svg += `<circle cx="${owlFX-2}" cy="${owlFY-6}" r="2" fill="#FFD700"/>`;
svg += `<circle cx="${owlFX+2}" cy="${owlFY-6}" r="2" fill="#FFD700"/>`;
svg += `<circle cx="${owlFX-2}" cy="${owlFY-6}" r="0.8" fill="#222"/>`;
svg += `<circle cx="${owlFX+2}" cy="${owlFY-6}" r="0.8" fill="#222"/>`;

// ═══ GOLDEN BUTTERFLY (ahead, leading upward) ═══
const bfx3 = cBaseX+80+Math.sin(mt*0.7)*20;
const bfy3 = cBaseY-40+Math.cos(mt*0.5)*12;
const bfW3 = Math.sin(mt*7)*5;
svg += `<ellipse cx="${bfx3-3}" cy="${bfy3}" rx="${3.5+bfW3*0.3}" ry="4.5" fill="#FFD700" opacity="0.85" transform="rotate(${-bfW3*2} ${bfx3-3} ${bfy3})"/>`;
svg += `<ellipse cx="${bfx3+3}" cy="${bfy3}" rx="${3.5+bfW3*0.3}" ry="4.5" fill="#FFD700" opacity="0.85" transform="rotate(${bfW3*2} ${bfx3+3} ${bfy3})"/>`;
svg += `<ellipse cx="${bfx3}" cy="${bfy3}" rx="0.8" ry="3" fill="#8B6914"/>`;
for (let i = 0; i < 5; i++) {
  const trx = bfx3-i*4;
  const tri3 = bfy3+i*1.5;
  svg += `<circle cx="${trx}" cy="${tri3}" r="${1.5-i*0.2}" fill="#FFD700" opacity="${0.2-i*0.03}"/>`;
}

// ── Snowflakes (gentle, first snow) ──
for (let i = 0; i < 20; i++) {
  const sfx = (Math.sin(i*73.1+5.3)*0.5+0.5)*w+Math.sin(mt*0.6+i*0.5)*12;
  const sfy = ((mt*6+i*(h/20))%(h+20))-10;
  const sfr = 1+Math.sin(i*2.3)*0.6;
  svg += `<circle cx="${sfx%w}" cy="${sfy}" r="${sfr}" fill="#FFF" opacity="${0.35+Math.sin(mt*1.5+i*0.7)*0.2}"/>`;
}

// ── Sun/Moon ──
if (!isN) {
  svg += `<circle cx="${w*0.15}" cy="${h*0.1}" r="${35+w1*8}" fill="#FFF8E0" opacity="0.1"/>`;
  svg += `<circle cx="${w*0.15}" cy="${h*0.1}" r="18" fill="#FFF8E0" opacity="0.35"/>`;
} else {
  svg += `<circle cx="${w*0.15}" cy="${h*0.08}" r="14" fill="#EDE8DF" opacity="0.8"/>`;
  svg += `<circle cx="${w*0.15+4}" cy="${h*0.08-3}" r="11" fill="#06001A" opacity="0.9"/>`;
}
